<?php if(!defined('APP_ENTRY'))exit;
$table='curriculum_subjects';$entity='curriculum subject';$heading='Curriculum mappings';
$courses=array_column(rows('SELECT id,course_name FROM courses ORDER BY course_name'),'course_name','id');
$classes=array_column(rows('SELECT c.id,CONCAT(c.class_name,\' — \',c.description,\' / \',t.academic_year,\' \',t.semester) label FROM classes c JOIN academic_terms t ON t.id=c.term_id ORDER BY c.class_name,t.academic_year'),'label','id');
$fields=['course_id'=>['label'=>'Program','options'=>$courses],'class_id'=>['label'=>'Subject / class','options'=>$classes],'year_level'=>['label'=>'Year level','options'=>[1=>'First year',2=>'Second year',3=>'Third year',4=>'Fourth year']],'prerequisite_class_id'=>['label'=>'Prerequisite (optional)','options'=>$classes,'optional'=>true]];
$validate=function($id){$co=id_field('course_id');$cl=id_field('class_id');$year=id_field('year_level');if($year>4)throw new DomainException('Year must be 1–4.');if(one('SELECT cs.id FROM curriculum_subjects cs JOIN classes oldc ON oldc.id=cs.class_id JOIN classes newc ON newc.id=? WHERE cs.course_id=? AND oldc.class_name=newc.class_name AND cs.id<>? LIMIT 1',[$cl,$co,$id??0]))throw new DomainException('This subject code is already mapped to the program; mappings carry forward to later terms.');$pre=post('prerequisite_class_id')===''?null:id_field('prerequisite_class_id');
 if($pre){$seen=[$cl=>true];$next=$pre;while($next){if(isset($seen[$next]))throw new DomainException('A prerequisite cannot form a cycle.');$seen[$next]=true;$r=one('SELECT year_level,prerequisite_class_id FROM curriculum_subjects WHERE course_id=? AND class_id=?',[$co,$next]);if(!$r||(int)$r['year_level']>$year)throw new DomainException('Prerequisite must already be mapped to this program in this or an earlier year.');$next=$r['prerequisite_class_id'];}}
 if($id){$old=one('SELECT course_id,class_id FROM curriculum_subjects WHERE id=?',[$id]);if($old&&((int)$old['course_id']!==$co||(int)$old['class_id']!==$cl)&&one('SELECT id FROM curriculum_subjects WHERE course_id=? AND prerequisite_class_id=? LIMIT 1',[$old['course_id'],$old['class_id']]))throw new DomainException('Remove dependent prerequisite mappings first.');}
 if(one('SELECT id FROM curriculum_subjects WHERE course_id=? AND prerequisite_class_id=? AND year_level<? LIMIT 1',[$co,$cl,$year]))throw new DomainException('A dependent subject is mapped to an earlier year.');
 return ['course_id'=>$co,'class_id'=>$cl,'year_level'=>$year,'prerequisite_class_id'=>$pre];};
$listSql='SELECT cs.id,co.course_name,c.class_name,cs.year_level,p.class_name prerequisite FROM curriculum_subjects cs JOIN courses co ON co.id=cs.course_id JOIN classes c ON c.id=cs.class_id LEFT JOIN classes p ON p.id=cs.prerequisite_class_id WHERE co.course_name LIKE ? OR c.class_name LIKE ? ORDER BY co.course_name,cs.year_level,c.class_name';$columns=['course_name'=>'Program','class_name'=>'Subject','year_level'=>'Year','prerequisite'=>'Prerequisite'];
?>
